<script>import{getLanguages}from'../logic/i18n.js';let{lang='fa',slug='home'}=$props();const ls=getLanguages();const nl=$derived(ls.find(l=>l.code!==lang)||ls[0]);function sw(){window.location.hash=`#/${nl.code}/${slug}`}</script><button class="ls" onclick={sw} title={nl.label} aria-label={nl.label}><span class="lc">{nl.code.toUpperCase()}</span></button><style>.ls{display:flex;align-items:center;justify-content:center;width:36px;height:36px;border:1px solid var(--color-border);border-radius:var(--radius-md);background:var(--color-bg-secondary);cursor:pointer;color:var(--color-text-secondary);font-family:var(--font-mono);font-size:var(--font-size-xs);font-weight:700;transition:all var(--transition-fast)}.ls:hover{background:var(--color-bg-hover);color:var(--color-accent)}.lc{line-height:1}</style>